    DataStore data;DiscoveryClient client;LinearLayout body;final ExecutorService jobs=Executors.newFixedThreadPool(4);final Map<Integer,JSONObject> library=new TreeMap<>(),metadata=new HashMap<>();final Map<Integer,Bitmap> posters=new HashMap<>();final Set<Integer> hidden=new HashSet<>(),seen=new HashSet<>(),missing=new HashSet<>();TasteCode.Card mine;String displayName="",selected;int revision;boolean dead;JSONArray friends=new JSONArray();
    public static String label(){return Loc.t("Compare taste");}
