    String t(String s){return Loc.t(s);}String f(String s,Object... values){return String.format(Locale.getDefault(),t(s),values);}int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);data=NoirApp.data;client=new DiscoveryClient(data.context);getWindow().setStatusBarColor(MainActivity.BLACK);getWindow().setNavigationBarColor(MainActivity.BLACK);if(saved!=null){displayName=saved.getString("name","");selected=saved.getString("selected");int[] ids=saved.getIntArray("hidden");if(ids!=null)for(int id:ids)hidden.add(id);}if(displayName.isEmpty())displayName=data.profiles.get(data.profileId).optString("name","Noir");page();body.addView(text("Loading your taste…",16,MainActivity.MUTED));String incoming=getIntent().getData()==null?null:getIntent().getData().toString();load(incoming);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(intent.getData()!=null&&mine!=null)open(intent.getData().toString());}
    @Override protected void onSaveInstanceState(Bundle saved){saved.putString("name",displayName);saved.putString("selected",selected);saved.putIntArray("hidden",hidden.stream().mapToInt(Integer::intValue).toArray());super.onSaveInstanceState(saved);}
    @Override protected void onDestroy(){dead=true;jobs.shutdownNow();super.onDestroy();}
    void post(Runnable action){runOnUiThread(()->{if(!dead&&!isFinishing())action.run();});}
    void load(String incoming){jobs.execute(()->{try{List<JSONObject> items=DataStore.objects(data.itemsShared());Map<Integer,JSONObject> index=new TreeMap<>();Map<String,Integer> groups=new HashMap<>();Set<Integer> watched=new HashSet<>();for(JSONObject item:items){int id=TasteCode.id(item.optString("imdb"));if(id==0)continue;JSONObject old=index.get(id);if(old==null||DataStore.rating10(item)>DataStore.rating10(old)||DataStore.rating10(item)==DataStore.rating10(old)&&item.optString("id").compareTo(old.optString("id"))<0)index.put(id,item);groups.put(item.optString("group"),id);if(DataStore.watched(item))watched.add(id);}List<TasteCode.Rating> ratings=new ArrayList<>();for(Map.Entry<Integer,JSONObject> e:index.entrySet())ratings.add(new TasteCode.Rating(e.getKey(),DataStore.rating10(e.getValue())));List<Integer> fav=new ArrayList<>();JSONArray favorites=data.settings().optJSONArray("favorites");if(favorites!=null)for(int i=0;i<favorites.length();i++){Integer id=groups.get(favorites.optString(i));if(id!=null)fav.add(id);}TasteCode.Card card=TasteCode.create(displayName,fav.stream().mapToInt(Integer::intValue).toArray(),ratings,null);JSONArray saved=readFriends();post(()->{library.putAll(index);seen.addAll(watched);mine=card;friends=saved;String latest=getIntent().getData()==null?incoming:getIntent().getData().toString();if(latest!=null)open(latest);else render();});}catch(Exception e){post(()->{page();body.addView(text("Couldn’t load your taste. Please retry.",16,MainActivity.MUTED));body.addView(button("Retry",()->load(incoming),true));});}});}
    AtomicFile friendFile(){return new AtomicFile(new File(data.context.getFilesDir(),"taste-friends.json"));}
    JSONArray readFriends(){try{AtomicFile file=friendFile();if(file.getBaseFile().length()>262144)return new JSONArray();JSONArray raw=new JSONArray(new String(file.readFully(),StandardCharsets.UTF_8)),valid=new JSONArray();for(int i=0;i<raw.length()&&valid.length()<128;i++){JSONObject row=raw.optJSONObject(i);if(row!=null&&TasteCode.decode(row.optString("code"))!=null)valid.put(row);}return valid;}catch(Exception e){return new JSONArray();}}
    boolean saveFriends(JSONArray values){try{DiscoveryClient.write(friendFile().getBaseFile(),values.toString().getBytes(StandardCharsets.UTF_8));friends=values;return true;}catch(Exception e){message("Couldn’t save friend cards. Check your profile storage.");return false;}}
    void open(String code){TasteCode.Card card=TasteCode.decode(code);if(card==null){if(mine!=null)render();message("This taste link is invalid or uses a newer version.");return;}selected=TasteCode.encode(card);JSONArray rows=new JSONArray();JSONObject first=new JSONObject();DataStore.put(first,"code",selected);DataStore.put(first,"savedAt",System.currentTimeMillis());rows.put(first);for(JSONObject row:DataStore.objects(friends))if(!selected.equals(row.optString("code"))&&rows.length()<128)rows.put(row);saveFriends(rows);render();}
    TasteCode.Card selection(){return TasteCode.create(displayName,mine.favorites,Arrays.asList(mine.ratings),hidden);}
    TextView text(String s,int size,int color){TextView v=new TextView(this);v.setText(t(s));v.setTextSize(size);v.setTextColor(color);v.setPadding(0,dp(6),0,dp(6));return v;}
    Button button(String s,Runnable click,boolean primary){Button b=new Button(this);b.setText(t(s));b.setAllCaps(false);b.setTextSize(15);b.setTextColor(primary?MainActivity.BLACK:MainActivity.WHITE);b.setBackground(MainActivity.bg(primary?MainActivity.GOLD:MainActivity.PANEL,dp(14)));b.setPadding(dp(14),dp(10),dp(14),dp(10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(lp);b.setOnClickListener(v->click.run());Motion.card(b);return b;}
    LinearLayout panel(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(18),dp(16),dp(18),dp(18));p.setBackground(MainActivity.bg(Color.rgb(25,24,23),dp(22)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(10),0,dp(10));body.addView(p,lp);return p;}
    void page(){revision++;ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(MainActivity.BLACK);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(20),dp(20),dp(20),dp(32));scroll.addView(body);setContentView(scroll);body.addView(button("‹ Back",this::finish,false));TextView title=text("Compare taste",30,MainActivity.WHITE);title.setTypeface(null,Typeface.BOLD);body.addView(title);Loc.apply(this);}
    void render(){if(mine==null)return;page();final int view=revision;body.addView(text("A link between friends. No account, no upload, just the stories you choose.",14,MainActivity.MUTED));LinearLayout card=panel();card.addView(text("My taste card",23,MainActivity.GOLD));card.addView(text("Preview everything below. Untick any title to leave it out of both favorites and ratings.",14,MainActivity.MUTED));card.addView(text("Display name included in your link",12,MainActivity.MUTED));EditText name=new EditText(this);name.setSingleLine();name.setText(displayName);name.setTextColor(MainActivity.WHITE);name.setContentDescription(t("Display name included in your link"));card.addView(name);TextView count=text("",13,MainActivity.GOLD);card.addView(count);card.addView(text("Only IMDb IDs, ratings and this name are included. No notes, dates or watch history.",12,MainActivity.MUTED));if(library.values().stream().filter(i->DataStore.rating10(i)>0).count()>60)card.addView(text("The first 60 rated IMDb titles are selected by ID. Hidden titles are never replaced automatically.",12,MainActivity.MUTED));
        LinearLayout choices=new LinearLayout(this);choices.setOrientation(LinearLayout.VERTICAL);ScrollView checkScroll=new ScrollView(this);checkScroll.setOnTouchListener((v,e)->{v.getParent().requestDisallowInterceptTouchEvent(e.getAction()!=MotionEvent.ACTION_UP&&e.getAction()!=MotionEvent.ACTION_CANCEL);return false;});checkScroll.addView(choices);card.addView(checkScroll,new LinearLayout.LayoutParams(-1,dp(216)));TextView qrHint=text("Your QR appears after you review and create your card.",14,MainActivity.MUTED);ImageView qr=new ImageView(this);qr.setContentDescription(t("Taste QR code"));qr.setScaleType(ImageView.ScaleType.FIT_CENTER);qr.setVisibility(View.GONE);final String[] link={null};final int[] generation={0};Button share=button("Share taste link",()->{if(link[0]==null)return;try{Intent intent=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,link[0]);startActivity(Intent.createChooser(intent,t("Share taste link")));}catch(ActivityNotFoundException e){message("No sharing apps available.");}},true);share.setEnabled(false);
        Runnable invalidate=()->{generation[0]++;link[0]=null;qr.setImageDrawable(null);qr.setVisibility(View.GONE);qrHint.setText(t("Review your changes, then create a fresh card."));share.setEnabled(false);TasteCode.Card chosen=selection();count.setText(f("%d favorites · %d ratings included",chosen.favorites.length,chosen.ratings.length));};Set<Integer> ids=new LinkedHashSet<>();for(int id:mine.favorites)ids.add(id);for(TasteCode.Rating r:mine.ratings)ids.add(r.id);for(int id:ids){JSONObject item=library.get(id);int rating=rating(mine,id);CheckBox box=new CheckBox(this);box.setText(item.optString("title")+(contains(mine.favorites,id)?"  ♥":"")+(rating>0?"  ·  "+rating+"/10":""));box.setTextColor(MainActivity.WHITE);box.setChecked(!hidden.contains(id));box.setPadding(0,dp(6),0,dp(6));box.setOnCheckedChangeListener((b,on)->{if(on)hidden.remove(id);else hidden.add(id);invalidate.run();});choices.addView(box);}TasteCode.Card initial=selection();count.setText(f("%d favorites · %d ratings included",initial.favorites.length,initial.ratings.length));name.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){displayName=TasteCode.name(s.toString());invalidate.run();}public void afterTextChanged(Editable s){}});
        card.addView(button("Create reviewed card",()->{displayName=TasteCode.name(name.getText().toString());name.setText(displayName);String reviewed=TasteCode.link(selection());final int token=generation[0];Button create=(Button)card.findViewWithTag("create");if(create!=null)create.setEnabled(false);jobs.execute(()->{try{Bitmap image=qrBitmap(reviewed);post(()->{if(view!=revision||token!=generation[0]){if(create!=null)create.setEnabled(true);return;}link[0]=reviewed;qr.setImageBitmap(image);qr.setVisibility(View.VISIBLE);qrHint.setText(t("Nothing is shared until you use Share."));share.setEnabled(true);if(create!=null)create.setEnabled(true);Motion.pop(qr);});}catch(Exception e){post(()->{if(create!=null)create.setEnabled(true);message("Couldn’t load your taste. Please retry.");});}});},true));card.getChildAt(card.getChildCount()-1).setTag("create");card.addView(qrHint);card.addView(qr,new LinearLayout.LayoutParams(-1,dp(300)));card.addView(share);
        LinearLayout opener=panel();EditText paste=new EditText(this);paste.setSingleLine();paste.setTextColor(MainActivity.WHITE);paste.setHintTextColor(MainActivity.MUTED);paste.setHint(t("Paste a noir://taste link"));paste.setContentDescription(t("Paste a noir://taste link"));paste.setFilters(new InputFilter[]{new InputFilter.LengthFilter(600)});opener.addView(paste);opener.addView(button("Open taste link",()->open(paste.getText().toString()),false));body.addView(text("Your circle",24,MainActivity.WHITE));body.addView(text("Friend cards are saved only in this profile. Delete them whenever you like.",12,MainActivity.MUTED));for(JSONObject row:DataStore.objects(friends)){String code=row.optString("code");TasteCode.Card friend=TasteCode.decode(code);if(friend==null)continue;LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);Button choose=button(friend.name.isEmpty()?t("Cinema friend"):friend.name,()->{selected=code;render();},code.equals(selected));line.addView(choose,new LinearLayout.LayoutParams(0,-2,1));Button delete=button("×",()->{JSONArray kept=new JSONArray();for(JSONObject old:DataStore.objects(friends))if(!code.equals(old.optString("code")))kept.put(old);if(saveFriends(kept)){if(code.equals(selected))selected=null;render();}},false);delete.setContentDescription(t("Delete friend card"));line.addView(delete,new LinearLayout.LayoutParams(dp(56),dp(52)));body.addView(line);}if(friends.length()==0)body.addView(text("Paste a friend’s link to find your next shared favorite.",14,MainActivity.MUTED));TasteCode.Card theirs=TasteCode.decode(selected);if(theirs!=null){LinearLayout comparison=panel();comparison(comparison,theirs,view);loadMetadata(theirs,comparison,view);}Motion.fadeIn(card);}
    static boolean contains(int[] ids,int id){for(int n:ids)if(n==id)return true;return false;}static int rating(TasteCode.Card c,int id){for(TasteCode.Rating r:c.ratings)if(r.id==id)return r.rating10;return 0;}
    static Bitmap qrBitmap(String text){QrCode qr=QrCode.encodeText(text,QrCode.Ecc.MEDIUM);int scale=Math.max(4,720/(qr.size+8)),size=(qr.size+8)*scale;int[] pixels=new int[size*size];Arrays.fill(pixels,Color.WHITE);for(int y=0;y<qr.size;y++)for(int x=0;x<qr.size;x++)if(qr.getModule(x,y))for(int dy=0;dy<scale;dy++)Arrays.fill(pixels,((y+4)*scale+dy)*size+(x+4)*scale,((y+4)*scale+dy)*size+(x+5)*scale,Color.BLACK);return Bitmap.createBitmap(pixels,size,size,Bitmap.Config.ARGB_8888);}
    Map<Integer,String[]> genres(){Map<Integer,String[]> result=new HashMap<>();for(Map.Entry<Integer,JSONObject> e:library.entrySet())result.put(e.getKey(),e.getValue().optString("genres").split("[·,]"));for(Map.Entry<Integer,JSONObject> e:metadata.entrySet()){JSONArray g=e.getValue().optJSONArray("genres");if(g!=null){String[] tags=new String[g.length()];for(int i=0;i<tags.length;i++)tags[i]=g.optString(i);result.put(e.getKey(),tags);}}return result;}
    void comparison(LinearLayout p,TasteCode.Card theirs,int view){if(view!=revision)return;p.removeAllViews();TasteCode.Match m=TasteCode.compare(mine,theirs,genres());p.addView(text(theirs.name.isEmpty()?t("Cinema friend"):theirs.name,19,MainActivity.MUTED));p.addView(text(m.score==null?t("A new connection"):f("%d%% in tune",m.score),38,MainActivity.GOLD));p.addView(text(f(m.overlap<5?"Only %d shared ratings · an early estimate from ratings, favorites and known genres.":m.correlation?"Based on rating correlation across %d shared titles.":"%d shared ratings · compared by rating distance.",m.overlap),13,MainActivity.MUTED));if(m.score==null)p.addView(text("Not enough shared evidence for a score yet.",14,MainActivity.MUTED));section(p,"You both loved",m.bothLoved,theirs,false,view);section(p,"They loved, you haven’t seen",Arrays.stream(m.unseenLoved).filter(id->!seen.contains(id)).toArray(),theirs,true,view);section(p,"Big disagreements",m.disagreements,theirs,false,view);p.addView(button("Refresh title details",()->{missing.clear();loadMetadata(theirs,p,view);},false));p.addView(text("Names and posters come from Cinemeta. Your name, ratings and taste link are never uploaded.",12,MainActivity.MUTED));}
    void section(LinearLayout p,String label,int[] ids,TasteCode.Card theirs,boolean add,int view){p.addView(text(label,20,MainActivity.WHITE));if(ids.length==0)p.addView(text("More shared stories will fill this space.",13,MainActivity.MUTED));for(int id:ids){JSONObject item=library.get(id),meta=metadata.get(id);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(MainActivity.bg(Color.rgb(43,37,29),dp(8)));if(posters.containsKey(id))art.setImageBitmap(posters.get(id));else if(item!=null){String file=item.optString("poster");jobs.execute(()->{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;String path=data.art(file).getPath();BitmapFactory.decodeFile(path,bounds);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(bounds.outWidth/options.inSampleSize>192||bounds.outHeight/options.inSampleSize>288)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeFile(path,options);post(()->{if(view==revision&&bitmap!=null){posters.put(id,bitmap);art.setImageBitmap(bitmap);}});});}row.addView(art,new LinearLayout.LayoutParams(dp(64),dp(94)));LinearLayout lines=new LinearLayout(this);lines.setOrientation(LinearLayout.VERTICAL);lines.setPadding(dp(12),0,0,0);lines.addView(text(item!=null?item.optString("title"):meta!=null?meta.optString("name"):TasteCode.imdb(id),16,MainActivity.WHITE));if(add){Button save=button(item!=null&&item.optBoolean("listed")?"✓ My List":"+ My List",()->{},false);save.setEnabled(item!=null||meta!=null);save.setOnClickListener(v->{save.setEnabled(false);jobs.execute(()->{try{JSONObject local=item;if(local==null){List<JSONObject> values=PhoneSeasonPlan.discoverItems(meta);if(values.isEmpty())throw new IOException();local=data.rememberPhoneItem(values.get(0));}JSONObject op=data.operation(local.optString("id"),"list");DataStore.put(op,"value",true);data.queue(op);data.syncSoon();post(()->{save.setText(t("✓ My List"));Motion.pop(save);});}catch(Exception e){post(()->{save.setEnabled(true);message("Couldn’t add this title. Please retry.");});}});});lines.addView(save);}else lines.addView(text(f("You %s · Them %s",rating(mine,id)>0?""+rating(mine,id):"♥",rating(theirs,id)>0?""+rating(theirs,id):"♥"),12,MainActivity.GOLD));if(item==null&&meta==null)lines.addView(text(missing.contains(id)?"Title unavailable · retry":"Finding title…",12,MainActivity.MUTED));row.addView(lines,new LinearLayout.LayoutParams(0,-2,1));p.addView(row);}}
    void loadMetadata(TasteCode.Card theirs,LinearLayout p,int view){java.util.concurrent.atomic.AtomicInteger done=new java.util.concurrent.atomic.AtomicInteger();Set<Integer> ids=new LinkedHashSet<>();for(int id:theirs.favorites)ids.add(id);for(TasteCode.Rating r:theirs.ratings)ids.add(r.id);ids.removeIf(id->library.containsKey(id)||metadata.containsKey(id)||missing.contains(id));final int total=ids.size();for(int id:ids)jobs.execute(()->{JSONObject found=null;Bitmap poster=null;for(String type:new String[]{"movie","series"})try{JSONObject seed=new JSONObject();DataStore.put(seed,"id",TasteCode.imdb(id));DataStore.put(seed,"noirType",type);JSONObject result=client.details(seed);if(!result.optString("name").isEmpty()){found=result;try{poster=client.art(found.optString("poster"));}catch(Exception ignored){}break;}}catch(Exception ignored){}final JSONObject result=found;final Bitmap image=poster;post(()->{if(result!=null){metadata.put(id,result);if(image!=null)posters.put(id,image);}else missing.add(id);int completed=done.incrementAndGet();if(view==revision&&(completed==total||completed%4==0))comparison(p,theirs,view);});});}
    void message(String s){if(!dead&&!isFinishing())new AlertDialog.Builder(this).setMessage(t(s)).setPositiveButton(t("OK"),null).show();}
